// Validate the diagnostic submission, normalize fields, and compute
// derived values (submittedAt ISO, testDate default, scorePercentile).
//
// Single CONFIG map at the top — the score-tier thresholds and
// percentile lookups MUST live ONLY here. The data-flow-integrity
// spec asserts these values do not appear elsewhere in the workflow.
const CONFIG = {
  // Static fallback tier-from-score lookup. Used when OpenRouter is
  // unreachable. Keep deterministic so tests are stable.
  satTierThresholds: [
    { min: 1500, max: 1600, tier: 'Elite' },
    { min: 1350, max: 1499, tier: 'Advanced' },
    { min: 1200, max: 1349, tier: 'Intermediate' },
    { min: 400,  max: 1199, tier: 'Foundations' }
  ],
  actTierThresholds: [
    { min: 33, max: 36, tier: 'Elite' },
    { min: 28, max: 32, tier: 'Advanced' },
    { min: 22, max: 27, tier: 'Intermediate' },
    { min: 1,  max: 21, tier: 'Foundations' }
  ],
  // Approximate percentile lookup tables (documented in setup-guide.md).
  // Values are interpolated linearly between anchors.
  satPercentileAnchors: [
    { score: 1600, pct: 99 },
    { score: 1500, pct: 98 },
    { score: 1400, pct: 94 },
    { score: 1300, pct: 87 },
    { score: 1200, pct: 74 },
    { score: 1100, pct: 56 },
    { score: 1000, pct: 39 },
    { score: 900,  pct: 25 },
    { score: 800,  pct: 14 },
    { score: 400,  pct: 1 }
  ],
  actPercentileAnchors: [
    { score: 36, pct: 99 },
    { score: 33, pct: 98 },
    { score: 30, pct: 93 },
    { score: 26, pct: 82 },
    { score: 22, pct: 64 },
    { score: 18, pct: 38 },
    { score: 14, pct: 13 },
    { score: 1,  pct: 1 }
  ],
  satRange: { min: 400, max: 1600 },
  actRange: { min: 1, max: 36 },
  validTestTypes: ['SAT', 'ACT']
};

function trimStr(v) { return typeof v === 'string' ? v.trim() : (v == null ? '' : String(v).trim()); }
function lcEmail(v) { return trimStr(v).toLowerCase(); }
function isEmail(s) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || '').trim()); }
function isYmd(s)   { return /^\d{4}-\d{2}-\d{2}$/.test(String(s || '').trim()); }

function percentileFromAnchors(score, anchors) {
  // anchors are sorted high -> low. Linear interpolation between brackets.
  const sorted = anchors.slice().sort((a, b) => b.score - a.score);
  if (score >= sorted[0].score) return sorted[0].pct;
  if (score <= sorted[sorted.length - 1].score) return sorted[sorted.length - 1].pct;
  for (let i = 0; i < sorted.length - 1; i++) {
    const hi = sorted[i];
    const lo = sorted[i + 1];
    if (score <= hi.score && score >= lo.score) {
      const span = hi.score - lo.score;
      const ratio = span === 0 ? 0 : (score - lo.score) / span;
      const pct = lo.pct + (hi.pct - lo.pct) * ratio;
      return Math.round(pct);
    }
  }
  return 1;
}

function tierFromThresholds(score, thresholds) {
  for (const t of thresholds) {
    if (score >= t.min && score <= t.max) return t.tier;
  }
  return 'Foundations';
}

const items = $input.all();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const src = (j.body && typeof j.body === 'object') ? j.body : j;

  // Accept multiple casings (Google Forms variant uses different keys)
  const studentName = trimStr(src.studentName ?? src.StudentName ?? src.student_name ?? src['Student Name']);
  const parentEmailRaw = trimStr(src.parentEmail ?? src.ParentEmail ?? src.parent_email ?? src['Parent Email']);
  const parentEmail = lcEmail(parentEmailRaw);
  const testTypeRaw = trimStr(src.testType ?? src.TestType ?? src.test_type ?? src['Test Type']);
  const testType = testTypeRaw.toUpperCase();
  const diagnosticScoreRaw = src.diagnosticScore ?? src.DiagnosticScore ?? src.diagnostic_score ?? src['Diagnostic Score'];
  const diagnosticScore = Number(diagnosticScoreRaw);
  const phone = trimStr(src.phone ?? src.Phone);
  const studentGradeLevel = trimStr(src.studentGradeLevel ?? src.gradeLevel ?? src.GradeLevel ?? src['Grade Level']);
  const notes = trimStr(src.notes ?? src.Notes);
  const testDateRaw = trimStr(src.testDate ?? src.TestDate ?? src['Test Date']);

  const errors = [];
  if (!studentName) errors.push('studentName is required');
  if (!parentEmailRaw) errors.push('parentEmail is required');
  else if (!isEmail(parentEmail)) errors.push('parentEmail is not a valid email address');
  if (!testTypeRaw) errors.push('testType is required');
  else if (!CONFIG.validTestTypes.includes(testType)) errors.push(`testType must be SAT or ACT (got: ${testTypeRaw})`);
  if (diagnosticScoreRaw === undefined || diagnosticScoreRaw === null || diagnosticScoreRaw === '') {
    errors.push('diagnosticScore is required');
  } else if (!Number.isFinite(diagnosticScore)) {
    errors.push('diagnosticScore must be a number');
  } else if (testType === 'SAT' && (diagnosticScore < CONFIG.satRange.min || diagnosticScore > CONFIG.satRange.max)) {
    errors.push(`diagnosticScore for SAT must be between ${CONFIG.satRange.min} and ${CONFIG.satRange.max} (got: ${diagnosticScore})`);
  } else if (testType === 'ACT' && (diagnosticScore < CONFIG.actRange.min || diagnosticScore > CONFIG.actRange.max)) {
    errors.push(`diagnosticScore for ACT must be between ${CONFIG.actRange.min} and ${CONFIG.actRange.max} (got: ${diagnosticScore})`);
  }

  const submittedAt = new Date().toISOString();
  const todayYmd = submittedAt.slice(0, 10);
  const testDate = isYmd(testDateRaw) ? testDateRaw : todayYmd;

  if (errors.length > 0) {
    out.push({ json: {
      studentName, parentEmail, testType, testTypeRaw,
      diagnosticScore: Number.isFinite(diagnosticScore) ? diagnosticScore : null,
      phone, studentGradeLevel, notes,
      testDate, submittedAt,
      scorePercentile: null,
      _error: true, _errors: errors, _reason: errors.join('; '),
      _nodeName: 'Code - Validate & Normalize'
    }});
    continue;
  }

  const anchors = testType === 'SAT' ? CONFIG.satPercentileAnchors : CONFIG.actPercentileAnchors;
  const thresholds = testType === 'SAT' ? CONFIG.satTierThresholds : CONFIG.actTierThresholds;
  const scorePercentile = percentileFromAnchors(diagnosticScore, anchors);
  const fallbackTier = tierFromThresholds(diagnosticScore, thresholds);

  out.push({ json: {
    studentName,
    parentEmail,
    testType,
    diagnosticScore,
    phone,
    studentGradeLevel,
    notes,
    testDate,
    submittedAt,
    scorePercentile,
    fallbackTier,
    _error: false, _errors: [], _reason: ''
  }});
}

return out;

// Merge the AI tier/rationale/parentParagraph onto the validated
// submission. Falls back to the deterministic threshold map +
// generic warm acknowledgment when OpenRouter fails or returns
// malformed JSON. Always returns a usable record.
function genericParentParagraph(studentName, testType, diagnosticScore) {
  return `Thank you for submitting ${studentName}'s ${testType} diagnostic results. We've received the score of ${diagnosticScore} and a member of our tutoring team will review the placement and reach out shortly to schedule a consultation. We look forward to partnering with your family on this prep journey.`;
}

const validated = $('Code - Validate & Normalize').item.json;
const ai = $input.first().json;

let tier = '';
let rationale = '';
let parentParagraph = '';
let aiUsed = false;
let aiError = '';
const VALID_TIERS = ['Foundations', 'Intermediate', 'Advanced', 'Elite'];

try {
  const raw = ai && ai.choices && ai.choices[0] && ai.choices[0].message && ai.choices[0].message.content;
  if (raw) {
    let parsed;
    try { parsed = JSON.parse(raw); } catch (e) {
      const m = String(raw).match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    }
    if (parsed && typeof parsed === 'object') {
      const tierCandidate = String(parsed.tier || '').trim();
      const rationaleCandidate = String(parsed.rationale || '').trim();
      const paragraphCandidate = String(parsed.parentParagraph || '').trim();
      if (VALID_TIERS.includes(tierCandidate) && rationaleCandidate.length > 0 && paragraphCandidate.length > 0) {
        tier = tierCandidate;
        rationale = rationaleCandidate;
        parentParagraph = paragraphCandidate;
        aiUsed = true;
      }
    }
  }
  if (ai && ai.error) aiError = String(ai.error.message || ai.error);
} catch (e) {
  aiError = String(e && e.message || e);
}

if (!aiUsed) {
  tier = validated.fallbackTier || 'Foundations';
  rationale = 'Tier assigned based on score range.';
  parentParagraph = genericParentParagraph(validated.studentName, validated.testType, validated.diagnosticScore);
}

return [{ json: {
  ...validated,
  tier,
  rationale,
  parentParagraph,
  aiUsed,
  aiError
} }];

